    tileLandscape.appendChild(el('span', {class:'sh-cta-link'}, [txt('Explore Landscape →')]));
    tileLandscape.onclick = function(){ window.prepPathOpen('landscape'); };
    ctaGrid.appendChild(tileLandscape);

