    const backLink = el('span', {style:'font-size:11px;letter-spacing:1.5px;text-transform:uppercase;color:var(--faint);font-weight:600;cursor:pointer;display:inline-block;transition:color .2s;'}, [txt('← Back')]);
    backLink.onmouseover = function(){ this.style.color='var(--gold)'; };
