    if(!document.getElementById('bh-cv-extras-css')){
      const cvExtrasCSS = `
        .bh-questions{ list-style:none; padding:0; display:flex; flex-direction:column; gap:8px; margin-bottom:14px; }
        .bh-q{ font-size:13.5px; color:var(--muted); line-height:1.7; padding-left:14px; border-left:2px solid rgba(166,87,46,0.25); }
        .bh-q strong{ color:var(--ink-soft); font-weight:600; }
        .bh-answer-profile{ font-size:11px; color:var(--gold); letter-spacing:1px; margin-bottom:10px; font-style:italic; }
        .cv-guidelines-steps .bh-header{ padding:16px 0; }
      `;
      const s2 = document.createElement('style');
      s2.id='bh-cv-extras-css'; s2.textContent=cvExtrasCSS; document.head.appendChild(s2);
    }

    function cvItem2(num, title, intro, lines, profile, answer){
      const item = el('div', {class:'bh-item', id:'cv-item-'+num});
      const header = el('div', {class:'bh-header'});
      const icon = el('div', {class:'bh-icon'}, [txt(num)]);
      const content = el('div', {class:'bh-content'});
      content.appendChild(el('div', {class:'bh-title'}, [txt(title)]));

      const introEl = el('div', {class:'bh-intro'});
      introEl.innerHTML = '<p>' + intro + '</p>';
      content.appendChild(introEl);

      if(lines && lines.length){
        const ql = el('ul', {class:'bh-questions'});
        lines.forEach(function(l){
          const li = el('li', {class:'bh-q'});
          li.innerHTML = l;
          ql.appendChild(li);
        });
        content.appendChild(ql);
      }

      if(answer){
        const tog = el('div', {class:'bh-toggle'});
        tog.innerHTML = '<span class="bh-toggle-plus-txt"></span>&nbsp;example <span class="bh-toggle-chevron">▼</span>';
        const answerBox = el('div', {class:'bh-answer'});
        answerBox.appendChild(el('div', {class:'bh-answer-profile'}, [txt(profile)]));
        const answerText = el('div', {class:'bh-answer-text'});
        answerText.innerHTML = answer;
        answerBox.appendChild(answerText);
        tog.onclick = function(){ item.classList.toggle('open'); };
        content.appendChild(tog);
        content.appendChild(answerBox);
      }

      header.appendChild(icon);
      header.appendChild(content);
      item.appendChild(header);
      return item;
    }

