  function renderDrillCategory(cat, subType){
    const data = (window.DRILLS || (typeof DRILLS !== 'undefined' ? DRILLS : {}))[cat.id];
    // Some categories (e.g. Chart Reading) group their levels one layer deeper,
    // inside a set of subTypes (Bar Charts, Pie Charts, ...), rather than
    // exposing `.levels` directly. Show a subtype picker first in that case.
    if(!subType && data && data.subTypes && data.subTypes.length){
      return renderDrillSubTypes(cat, data);
    }
    if(!document.getElementById('drills-css')){
      const drCSS=`.drills-list{display:flex;flex-direction:column;gap:0;border-bottom:1px solid var(--line);} .drills-item{display:flex;align-items:center;justify-content:space-between;padding:18px 2px;border-top:1px solid var(--line);cursor:pointer;transition:opacity .15s;} .drills-item:hover{opacity:0.7;padding-left:8px;} .drills-item-left{} .drills-item-title{font-family:var(--serif-heading);font-size:19px;font-weight:500;color:var(--ink);margin-bottom:3px;} .drills-item-desc{font-size:13px;color:var(--muted);line-height:1.6;} .drills-item-arrow{color:var(--gold);font-size:18px;flex-shrink:0;margin-left:16px;} .drills-levels-badge{font-size:10px;letter-spacing:1.5px;text-transform:uppercase;color:var(--gold);font-weight:700;}`;
      const ds=document.createElement('style');ds.id='drills-css';ds.textContent=drCSS;document.head.appendChild(ds);
    }
    const pageTitle = subType ? (cat.label + ' - ' + subType.label) : cat.label;
    const pageDesc = subType ? subType.desc : cat.desc;
    const quizTitlePrefix = subType ? (cat.label + ' - ' + subType.label) : cat.label;
    const wrap = pageWrap('Numeric Foundations Drills', pageTitle, pageDesc);
    const levels = subType ? (subType.levels || []) : (data && data.levels ? data.levels : []);
    if(!levels.length){
      wrap.appendChild(el('p', {class:'app-empty'}, [txt('No drills found for this category yet.')]));
      return wrap;
    }
    const list = el('div', {class:'drills-list'});
    levels.forEach(function(lv, idx){
      const item = el('div', {class:'drills-item', role:'button', tabindex:'0'});
      const left = el('div', {class:'drills-item-left'});
      const levelLabel = lv.label || ('Level ' + (lv.level || (idx+1)));
      const diffLabel = idx === 0 ? 'Foundation' : idx === 1 ? 'Intermediate' : 'Advanced';
      left.appendChild(el('div', {class:'drills-item-title'}, [txt(levelLabel)]));
      left.appendChild(el('div', {class:'drills-item-desc'}, [txt(lv.desc || (lv.questions.length + ' questions'))]));
      left.appendChild(el('div', {class:'drills-levels-badge', style:'margin-top:5px;'}, [txt(diffLabel + ' · ' + (lv.questions ? lv.questions.length : 0) + ' questions')]));
      const arrow = el('span', {class:'drills-item-arrow'}, [txt('→')]);
      item.appendChild(left);
      item.appendChild(arrow);
      item.onclick = function(){ showApp('quiz', function(){ return renderQuiz(lv.questions, quizTitlePrefix + ' - ' + levelLabel, 'drills'); }); };
      list.appendChild(item);
    });
    wrap.appendChild(list);
    return wrap;
  }

  function renderDrillSubTypes(cat, data){
    const wrap = pageWrap('Numeric Foundations Drills', cat.label, cat.desc);
    if(!document.getElementById('drills-css')){
      const drCSS=`.drills-list{display:flex;flex-direction:column;gap:0;border-bottom:1px solid var(--line);} .drills-item{display:flex;align-items:center;justify-content:space-between;padding:18px 2px;border-top:1px solid var(--line);cursor:pointer;transition:opacity .15s;} .drills-item:hover{opacity:0.7;padding-left:8px;} .drills-item-left{} .drills-item-title{font-family:var(--serif-heading);font-size:19px;font-weight:500;color:var(--ink);margin-bottom:3px;} .drills-item-desc{font-size:13px;color:var(--muted);line-height:1.6;} .drills-item-arrow{color:var(--gold);font-size:18px;flex-shrink:0;margin-left:16px;} .drills-levels-badge{font-size:10px;letter-spacing:1.5px;text-transform:uppercase;color:var(--gold);font-weight:700;}`;
      const ds=document.createElement('style');ds.id='drills-css';ds.textContent=drCSS;document.head.appendChild(ds);
    }
    const list = el('div', {class:'drills-list'});
    data.subTypes.forEach(function(st){
      const item = el('div', {class:'drills-item', role:'button', tabindex:'0'});
      const left = el('div', {class:'drills-item-left'});
      const numLevels = st.levels ? st.levels.length : 0;
      const numQuestions = st.levels ? st.levels.reduce(function(sum, lv){ return sum + (lv.questions ? lv.questions.length : 0); }, 0) : 0;
      left.appendChild(el('div', {class:'drills-item-title'}, [txt(st.label)]));
      left.appendChild(el('div', {class:'drills-item-desc'}, [txt(st.desc || '')]));
      left.appendChild(el('div', {class:'drills-levels-badge', style:'margin-top:5px;'}, [txt(numLevels + ' levels · ' + numQuestions + ' questions')]));
      const arrow = el('span', {class:'drills-item-arrow'}, [txt('→')]);
      item.appendChild(left);
      item.appendChild(arrow);
      item.onclick = function(){ showApp('drill-cat', function(){ return renderDrillCategory(cat, st); }); };
      list.appendChild(item);
    });
    wrap.appendChild(list);
    return wrap;
  }

  function renderLevelPicker(name, tests, src){
    const wrap = pageWrap('Quant Skillset', name, '');
    const grid = el('div', {class:'app-card-grid-3'});
    tests.forEach(function(lv){
      const title = name + ' - ' + (lv.label || ('Level '+lv.level));
      const card = el('div', {class:'app-mini-card', role:'button', tabindex:'0'});
      card.appendChild(el('h4',{},[txt(lv.label||('Level '+lv.level))]));
      card.appendChild(el('p',{},[txt((lv.questions?lv.questions.length:0)+' questions')]));
      card.onclick = function(){ showApp('quiz', function(){ return renderQuiz(lv.questions, title, src); }); };
      grid.appendChild(card);
    });
    wrap.appendChild(grid);
    return wrap;
  }

  /* ---------- QUIZ ENGINE ---------- */
  function renderQuiz(questions, title, sourceLabel){
    if(!document.getElementById('quiz-theme-css')){
      const quizThemeCSS = `
        html[data-theme="light"]{
          --qz-bg: #ffffff;
          --qz-surface: #f9f7f2;
          --qz-surface-alt: #f5f5f5;
          --qz-surface-warm: #fdf9f0;
          --qz-modal-bg: #ffffff;
          --qz-border: #e8e4dc;
          --qz-border-soft: #f0ede6;
          --qz-border-warm: #d9ceb5;
          --qz-input-border: #ddd;
          --qz-ink: #111111;
          --qz-ink-soft: #333333;
          --qz-muted: #888888;
          --qz-text-warm: #8A4523;
          --qz-good-bg: #f0faf4;
          --qz-good-border: #a8d8b8;
          --qz-good-text: #2d7a4f;
          --qz-bad-text: #c0392b;
          --qz-badge-bg: #111111;
          --qz-badge-text: #ffffff;
          --qz-pause-overlay-bg: rgba(255,255,255,0.97);
        }
        :root, html[data-theme="dark"]{
          --qz-bg: #0b0b0c;
          --qz-surface: #17171a;
          --qz-surface-alt: #1c1c1f;
          --qz-surface-warm: #201a10;
          --qz-modal-bg: #1c1c1f;
          --qz-border: rgba(255,255,255,0.12);
          --qz-border-soft: rgba(255,255,255,0.08);
          --qz-border-warm: rgba(166,87,46,0.35);
          --qz-input-border: rgba(255,255,255,0.20);
          --qz-ink: #f5f1e9;
          --qz-ink-soft: #cfd0d6;
          --qz-muted: #9a9a9e;
          --qz-text-warm: #BF6B3E;
          --qz-good-bg: rgba(95,217,143,0.14);
          --qz-good-border: rgba(95,217,143,0.35);
          --qz-good-text: #5fd98f;
          --qz-bad-text: #e2725c;
          --qz-badge-bg: #BF6B3E;
          --qz-badge-text: #0b0b0c;
          --qz-pause-overlay-bg: rgba(11,11,12,0.97);
        }
      `;
      const qs = document.createElement('style'); qs.id = 'quiz-theme-css'; qs.textContent = quizThemeCSS; document.head.appendChild(qs);
    }
    const scoreKey = 'pp_score_' + title.replace(/\s+/g,'_');
    const bestRaw = localStorage.getItem(scoreKey);
    const bestScore = bestRaw ? JSON.parse(bestRaw) : null;
    const TIPS = allTips();

    function parseExplain(html){
      return parseTipLinks(html, TIPS);
    }

    function formatSolution(text){
      if(!text) return '';
      const headers = ['Step by Step','The Key Idea','The Theory','The Metaphor','The Tricky Part','Mental Maths Tip','Variations to Watch For'];
      const escapedHeaders = headers.map(function(h){ return h.replace(/[.*+?^${}()|[\]\\]/g, '\\$&'); });
      const splitRe = new RegExp('(' + escapedHeaders.join('|') + ')\\n', 'g');
      const parts = text.split(splitRe);
      let html = '';
      let leading = parts[0].trim();
      if(leading){
        html += '<div style="margin-bottom:14px;">' + parseExplain(leading.replace(/\n/g,'<br>')) + '</div>';
      }
      for(let i=1; i<parts.length; i+=2){
        const heading = parts[i];
        const body = (parts[i+1]||'').trim();
        html += '<div style="margin-bottom:14px;">';
        html += '<strong style="color:var(--qz-ink);font-size:12px;letter-spacing:1.5px;display:block;margin-bottom:5px;">'+heading+'</strong>';
        html += '<div>' + parseExplain(body.replace(/\n/g,'<br>')) + '</div>';
        html += '</div>';
      }
      return html;
    }

    function formatAnswer(val){
      if(!val) return val;
      var num = val.toString().replace(/,/g,'');
      if(/^-?\d+(\.\d+)?$/.test(num)){
        var parts = num.split('.');
        parts[0] = parts[0].replace(/\B(?=(\d{3})+(?!\d))/g, ',');
        return parts.join('.');
      }
      return val;
    }

    function showPreTest(onStart){
      const shell = el('div', {id:'quiz-shell', style:'position:fixed;inset:0;background:var(--qz-bg);z-index:9999;font-family:Inter,sans-serif;overflow-y:auto;'});
      const inner = el('div', {style:'max-width:520px;margin:0 auto;padding:48px 24px;'});
      const back = el('div', {style:'font-size:13px;color:var(--qz-muted);cursor:pointer;'}, [txt('← Back')]);
      back.onclick = function(){ shell.remove(); document.getElementById('app-root').style.display='block'; goBack(); };
      const preMainBtn = el('div', {style:'font-size:13px;color:#A6572E;font-weight:600;cursor:pointer;'}, [txt('Main Page')]);
      preMainBtn.onclick = function(){ shell.remove(); document.getElementById('app-root').style.display='block'; goMain(); };
      const preHeaderRow = el('div', {style:'display:flex;align-items:center;justify-content:space-between;margin-bottom:32px;'});
      preHeaderRow.appendChild(back);
      preHeaderRow.appendChild(preMainBtn);
      inner.appendChild(preHeaderRow);
      inner.appendChild(el('div', {style:'font-family:var(--serif-heading);font-size:28px;font-weight:500;color:var(--qz-ink);margin-bottom:4px;'}, [txt(title)]));
      inner.appendChild(el('div', {style:'font-size:14px;color:var(--qz-muted);margin-bottom:28px;'}, [txt('Practice Test')]));
      const stats = el('div', {style:'display:grid;grid-template-columns:repeat(3,1fr);gap:12px;margin-bottom:24px;'});
      const secsPerQ = sourceLabel === 'tests' ? 120 : 60;
      const totalMins = Math.round(questions.length * secsPerQ / 60);
      [[questions.length,'Questions'],[totalMins,'Minutes'],[secsPerQ+'s','Per question']].forEach(function(pair){
        const card = el('div', {style:'border:1px solid var(--qz-border);border-radius:3px;padding:16px;text-align:center;'});
        card.innerHTML = '<div style="font-size:28px;font-weight:700;color:#A6572E;line-height:1;">'+pair[0]+'</div><div style="font-size:13px;color:var(--qz-muted);margin-top:4px;">'+pair[1]+'</div>';
        stats.appendChild(card);
      });
      inner.appendChild(stats);
      if(bestScore !== null){
        const bs = el('div', {style:'background:var(--qz-surface-warm);border:1px solid var(--qz-border-warm);border-radius:3px;padding:12px 16px;margin-bottom:16px;font-size:13px;color:var(--qz-text-warm);'});
        bs.innerHTML = 'Your best score: <strong>'+bestScore.score+' / '+bestScore.total+'</strong> ('+Math.round(bestScore.score/bestScore.total*100)+'%)';
        inner.appendChild(bs);
      }
      const how = el('div', {style:'background:var(--qz-surface);border:1px solid var(--qz-border);border-radius:3px;padding:20px;margin-bottom:24px;'});
      how.innerHTML = '<div style="font-size:10px;letter-spacing:2px;text-transform:uppercase;color:var(--qz-muted);font-weight:700;margin-bottom:12px;">How it works</div>';
      ['Read the answer format instruction carefully before typing','You can skip a question by pressing Enter with no answer','The timer starts when you press Start','You can pause at any time - but the real assessment will not allow this, so use pausing sparingly','Full worked answers shown at the end'].forEach(function(item){
        const p = el('div', {style:'font-size:13.5px;color:var(--qz-ink-soft);padding:10px 0;'}, [txt(item)]);
        how.appendChild(p);
      });
      inner.appendChild(how);
      const diff = el('div', {style:'font-size:13px;color:var(--qz-muted);margin-bottom:24px;'});
      const levelMatch = title.match(/[--]\s*(Level\s*\d+|Foundation|Intermediate|Advanced)/i);
      const diffLabel = levelMatch ? levelMatch[1] : (sourceLabel === 'tests' ? 'Calibrated to real assessment difficulty' : null);
      if(diffLabel){ diff.innerHTML = '<strong style="color:var(--qz-ink-soft);">Difficulty:</strong> ' + diffLabel; } else { diff.style.display = 'none'; }
      inner.appendChild(diff);
      const startBtn = el('button', {style:'width:100%;padding:16px;border:1.5px solid #A6572E;border-radius:3px;background:var(--qz-bg);color:#A6572E;font-size:16px;font-weight:700;cursor:pointer;font-family:Inter,sans-serif;transition:all .2s;'});
      startBtn.textContent = 'Start test →';
      startBtn.onmouseover = function(){ this.style.background='var(--qz-surface-warm)'; };
      startBtn.onmouseout = function(){ this.style.background='var(--qz-bg)'; };
      startBtn.onclick = function(){ shell.remove(); onStart(); };
      inner.appendChild(startBtn);
      shell.appendChild(inner);
      document.getElementById('app-root').style.display='none';
      document.body.appendChild(shell);
    }

    function showCameraModal(onDone){
      const overlay = el('div', {style:'position:fixed;inset:0;background:rgba(0,0,0,0.45);z-index:10001;display:flex;align-items:center;justify-content:center;'});
      const modal = el('div', {style:'background:var(--qz-modal-bg);border-radius:3px;padding:36px 32px;max-width:380px;width:90%;text-align:center;'});
      modal.innerHTML = '<div style="font-size:32px;margin-bottom:16px;">📷</div><div style="font-size:18px;font-weight:700;color:var(--qz-ink);margin-bottom:12px;">Enable self view?</div><div style="font-size:14px;color:var(--qz-ink-soft);line-height:1.65;margin-bottom:10px;">In the real assessment you will likely be recorded. Would you like to turn on your camera so you can practise under similar conditions?</div><div style="font-size:12px;color:var(--qz-muted);margin-bottom:24px;">We do not record or store any footage.</div>';
      const btnRow = el('div', {style:'display:flex;gap:12px;justify-content:center;'});
      const yesBtn = el('button', {style:'padding:12px 24px;background:#A6572E;color:#fff;border:none;border-radius:3px;font-size:14px;font-weight:600;cursor:pointer;font-family:Inter,sans-serif;'}, [txt('Yes, turn on camera')]);
      yesBtn.onclick = function(){
        overlay.remove();
        navigator.mediaDevices && navigator.mediaDevices.getUserMedia({video:true}).then(function(stream){
          const pip = el('video', {style:'position:fixed;bottom:80px;right:16px;width:120px;height:90px;border-radius:3px;border:2px solid var(--qz-border);z-index:10000;object-fit:cover;'});
          pip.srcObject = stream; pip.autoplay = true; pip.muted = true; pip.id = 'quiz-pip';
          document.body.appendChild(pip);
        }).catch(function(){});
        onDone();
      };
      const noBtn = el('button', {style:'padding:12px 24px;background:var(--qz-modal-bg);color:var(--qz-ink-soft);border:1px solid var(--qz-input-border);border-radius:3px;font-size:14px;cursor:pointer;font-family:Inter,sans-serif;'}, [txt('No thanks')]);
      noBtn.onclick = function(){ overlay.remove(); onDone(); };
      btnRow.appendChild(yesBtn); btnRow.appendChild(noBtn);
      modal.appendChild(btnRow); overlay.appendChild(modal);
      overlay.onclick = function(e){ if(e.target===overlay) overlay.remove(); };
      document.body.appendChild(overlay);
    }

    function showTipModal(key){
      const tip = TIPS[key];
      if(!tip) return;
      const overlay = el('div', {style:'position:fixed;inset:0;background:rgba(0,0,0,0.45);z-index:10002;display:flex;align-items:center;justify-content:center;'});
      const modal = el('div', {style:'background:var(--qz-modal-bg);border-radius:3px;padding:28px;max-width:420px;width:90%;position:relative;'});
      const closeBtn = el('button', {style:'position:absolute;top:14px;right:16px;background:none;border:none;font-size:18px;cursor:pointer;color:var(--qz-muted);'}, [txt('×')]);
      closeBtn.onclick = function(){ overlay.remove(); };
      const tag = el('div', {style:'display:inline-block;background:var(--qz-good-bg);border:1px solid var(--qz-good-border);border-radius:3px;padding:3px 10px;font-size:10px;letter-spacing:1.5px;text-transform:uppercase;color:var(--qz-good-text);font-weight:700;margin-bottom:12px;'}, [txt(tip.tag || 'Tip')]);
      const titleEl = el('div', {style:'font-size:18px;font-weight:700;color:var(--qz-ink);margin-bottom:12px;'}, [txt(tip.title)]);
      const bodyEl = el('div', {style:'font-size:14px;color:var(--qz-ink-soft);line-height:1.7;margin-bottom:20px;'}, [txt(tip.body)]);
      const readMore = el('button', {style:'width:100%;padding:14px;background:#A6572E;color:#fff;border:none;border-radius:3px;font-size:14px;font-weight:600;cursor:pointer;font-family:Inter,sans-serif;'}, [txt((tip.linkLabel || 'Read more') + ' \u2192')]);
      readMore.onclick = function(){
        overlay.remove();
        var qs=document.getElementById('quiz-shell'); if(qs) qs.remove();
        var pip=document.getElementById('quiz-pip'); if(pip){ pip.srcObject&&pip.srcObject.getTracks().forEach(function(t){t.stop();}); pip.remove(); }
        document.getElementById('app-root').style.display='block';
        var target = tipSectionKey(tip.link) || 'mentalmaths';
        openResourceSection(target);
      };
      modal.appendChild(closeBtn); modal.appendChild(tag); modal.appendChild(titleEl); modal.appendChild(bodyEl); modal.appendChild(readMore);
      overlay.appendChild(modal);
      overlay.onclick = function(e){ if(e.target===overlay) overlay.remove(); };
      document.body.appendChild(overlay);
    }

    function startQuiz(){
      let idx = 0, score = 0;
      const answers = new Array(questions.length).fill(null);
      const secsPerQ = sourceLabel === 'tests' ? 120 : 60;
      const TOTAL_SECS = questions.length * secsPerQ;
      let secsLeft = TOTAL_SECS;
      let timerInterval = null;
      let isPaused = false;
      let hideOnPause = true;

      const shell = el('div', {id:'quiz-shell', style:'position:fixed;inset:0;background:var(--qz-bg);z-index:9999;display:flex;flex-direction:column;font-family:Inter,sans-serif;'});
      document.getElementById('app-root').style.display = 'none';

      const topBar = el('div', {style:'display:flex;align-items:center;justify-content:center;gap:20px;padding:0 32px;height:52px;border-bottom:1px solid var(--qz-border);background:var(--qz-bg);flex-shrink:0;flex-wrap:wrap;'});
      const timerEl = el('div', {style:'display:flex;align-items:center;gap:6px;font-size:13px;color:var(--qz-ink-soft);font-weight:600;'});
      timerEl.innerHTML = '<svg width="14" height="14" viewBox="0 0 24 24" fill="none" stroke="#A6572E" stroke-width="2" stroke-linecap="round" stroke-linejoin="round"><circle cx="12" cy="12" r="10"/><polyline points="12,6 12,12 16,14"/></svg><span id="quiz-time">'+formatTime(secsLeft)+'</span>';
      const qLabel = el('div', {id:'quiz-qlabel', style:'font-size:13px;color:var(--qz-ink-soft);font-weight:600;'}, [txt('Question 1 of '+questions.length)]);
      const pauseBtn = el('button', {style:'font-size:12px;color:var(--qz-ink-soft);background:none;border:1px solid var(--qz-input-border);border-radius:3px;padding:5px 14px;cursor:pointer;font-family:Inter,sans-serif;'}, [txt('Pause')]);
      const hideToggleLabel = el('label', {style:'display:flex;align-items:center;gap:6px;font-size:11.5px;color:var(--qz-muted);cursor:pointer;white-space:nowrap;'});
      const hideToggleCheckbox = el('input', {type:'checkbox', checked:'checked', style:'cursor:pointer;'});
      hideToggleCheckbox.checked = true;
      hideToggleCheckbox.onchange = function(){ hideOnPause = hideToggleCheckbox.checked; };
      hideToggleLabel.appendChild(hideToggleCheckbox);
      hideToggleLabel.appendChild(txt('Hide question when paused'));
      const endBtn = el('button', {style:'font-size:12px;color:var(--qz-muted);background:none;border:1px solid var(--qz-input-border);border-radius:3px;padding:5px 14px;cursor:pointer;font-family:Inter,sans-serif;'}, [txt('End test')]);
      endBtn.onclick = function(){ stopTimer(); renderResults(); };
      const mainBtn = el('button', {style:'font-size:12px;color:#A6572E;background:none;border:1px solid rgba(166,87,46,0.4);border-radius:3px;padding:5px 14px;cursor:pointer;font-family:Inter,sans-serif;font-weight:600;'}, [txt('Main Page')]);
      mainBtn.onclick = function(){ stopTimer(); cleanupQuiz(); PrepPathGoMain(); };
      topBar.appendChild(timerEl); topBar.appendChild(qLabel); topBar.appendChild(pauseBtn); topBar.appendChild(hideToggleLabel); topBar.appendChild(endBtn); topBar.appendChild(mainBtn);
      shell.appendChild(topBar);

      const thread = el('div', {style:'flex:1;overflow-y:auto;padding:24px 0 140px;background:var(--qz-bg);position:relative;'});
      const threadInner = el('div', {style:'max-width:520px;margin:0 auto;padding:0 20px;'});
      thread.appendChild(threadInner);
      shell.appendChild(thread);

      const pauseOverlay = el('div', {style:'position:fixed;inset:0;background:var(--qz-pause-overlay-bg);z-index:10;display:none;flex-direction:column;align-items:center;justify-content:center;text-align:center;padding:24px;'});
      pauseOverlay.innerHTML = '<div style="font-size:22px;font-weight:700;color:var(--qz-ink);margin-bottom:10px;">Test paused</div><div style="font-size:14px;color:var(--qz-muted);margin-bottom:24px;max-width:340px;">Your timer has stopped. Remember - the real assessment will most likely not allow you to pause, so use this sparingly.</div>';
      const resumeBtn = el('button', {style:'padding:12px 28px;background:#A6572E;color:#fff;border:none;border-radius:3px;font-size:14px;font-weight:700;cursor:pointer;font-family:Inter,sans-serif;'}, [txt('Resume test')]);
      pauseOverlay.appendChild(resumeBtn);
      shell.appendChild(pauseOverlay);

      const pausedBadge = el('div', {style:'display:none;position:fixed;top:64px;left:50%;transform:translateX(-50%);background:var(--qz-badge-bg);color:var(--qz-badge-text);font-size:12px;font-weight:600;padding:8px 18px;border-radius:20px;z-index:11;box-shadow:0 4px 16px rgba(0,0,0,0.2);'}, [txt('Paused - timer stopped')]);
      shell.appendChild(pausedBadge);

      function setPaused(p){
        isPaused = p;
        if(p){
          stopTimer();
          answerInput.disabled = true; submitBtn.disabled = true;
          if(hideOnPause){
            pauseOverlay.style.display = 'flex';
          } else {
            pausedBadge.style.display = 'block';
          }
          pauseBtn.textContent = 'Resume';
        } else {
          answerInput.disabled = false; submitBtn.disabled = false;
          pauseOverlay.style.display = 'none';
          pausedBadge.style.display = 'none';
          pauseBtn.textContent = 'Pause';
          startTimer();
          answerInput.focus();
        }
      }
      pauseBtn.onclick = function(){ setPaused(!isPaused); };
      resumeBtn.onclick = function(){ setPaused(false); };

      const bottomBar = el('div', {style:'position:fixed;bottom:0;left:0;right:0;padding:12px 0;background:var(--qz-bg);border-top:1px solid var(--qz-border);display:flex;gap:10px;align-items:center;justify-content:center;'});
      const answerInput = el('input', {type:'text', placeholder:'Type your answer...', style:'width:360px;max-width:80vw;padding:12px 16px;border:1.5px solid #A6572E;border-radius:3px;font-size:15px;font-family:Inter,sans-serif;outline:none;color:var(--qz-ink);background:var(--qz-bg);'});
      const submitBtn = el('button', {style:'width:44px;height:44px;background:#A6572E;border:none;border-radius:3px;cursor:pointer;display:flex;align-items:center;justify-content:center;flex-shrink:0;'});
      submitBtn.innerHTML = '<svg width="18" height="18" viewBox="0 0 24 24" fill="none" stroke="#fff" stroke-width="2.5" stroke-linecap="round" stroke-linejoin="round"><line x1="22" y1="2" x2="11" y2="13"/><polygon points="22,2 15,22 11,13 2,9"/></svg>';
      bottomBar.appendChild(answerInput); bottomBar.appendChild(submitBtn);
      shell.appendChild(bottomBar);
      document.body.appendChild(shell);

      function formatTime(s){ return String(Math.floor(s/60)).padStart(2,'0')+':'+String(s%60).padStart(2,'0'); }
      function startTimer(){ timerInterval = setInterval(function(){ secsLeft--; var el2=document.getElementById('quiz-time'); if(el2) el2.textContent=formatTime(secsLeft); if(secsLeft<=0){ stopTimer(); renderResults(); } },1000); }
      function stopTimer(){ if(timerInterval){ clearInterval(timerInterval); timerInterval=null; } }
      function normalize(s){ return (s||'').toString().toLowerCase().replace(/\s+/g,' ').replace(/[£$%,]/g,'').trim(); }
      function cleanupQuiz(){ stopTimer(); var s=document.getElementById('quiz-shell'); if(s) s.remove(); var pip=document.getElementById('quiz-pip'); if(pip){ pip.srcObject&&pip.srcObject.getTracks().forEach(function(t){t.stop();}); pip.remove(); } document.getElementById('app-root').style.display='block'; }

      function unitSignature(s){
        s = (s||'').toString().trim();
        if(/^-?[£$]/.test(s)) return s.match(/[£$]/)[0] + (/k\b/i.test(s)?'k':/m\b/i.test(s)?'m':'');
        if(/%/.test(s)) return '%';
        if(/^-?[\d,.]+\$/.test(s)) return 'num';
        return null;
      }

      function buildTableHTML(table){
        if(!table) return '';
        var nCols = table.headers.length;
        var colMax = [], colConsistent = [];
        for(var c=0; c<nCols; c++){
          var cellVals = table.rows.map(function(r){ return (r[c]||'').toString(); });
          var sigs = cellVals.map(unitSignature).filter(function(s){ return s!==null; });
          var uniqueSigs = sigs.filter(function(s,i){ return sigs.indexOf(s)===i; });
          colConsistent[c] = c>0 && uniqueSigs.length===1 && sigs.length===cellVals.length;
          var vals = cellVals.map(function(v){ return parseChartValue(v); }).filter(function(v){ return !isNaN(v); });
          colMax[c] = vals.length ? Math.max.apply(null, vals.map(Math.abs)) : 0;
        }
        var numericCols = colMax.map(function(m,c){ return colConsistent[c] && m>0; });
        var html = '<div style="overflow-x:auto;margin:14px 0;border:1px solid var(--qz-border);border-radius:3px;"><table style="width:100%;border-collapse:collapse;font-size:13.5px;">';
        html += '<thead><tr>';
        table.headers.forEach(function(h){ html += '<th style="text-align:left;padding:9px 14px;background:var(--qz-surface);border-bottom:1px solid var(--qz-border-soft);color:var(--qz-ink-soft);font-weight:700;white-space:nowrap;">'+h+'</th>'; });
        html += '</tr></thead><tbody>';
        table.rows.forEach(function(row, ri){
          html += '<tr style="background:'+(ri%2===0?'var(--qz-bg)':'var(--qz-surface)')+';">';
          row.forEach(function(cell, ci){
            if(numericCols[ci]){
              var v = parseChartValue((cell||'').toString());
              var pct = !isNaN(v) && colMax[ci]>0 ? Math.min(100, Math.abs(v)/colMax[ci]*100) : 0;
              html += '<td style="padding:8px 14px;border-bottom:1px solid var(--qz-border-soft);position:relative;">';
              html += '<div style="position:absolute;left:0;top:4px;bottom:4px;width:'+pct+'%;background:rgba(166,87,46,0.18);border-radius:3px;"></div>';
              html += '<span style="position:relative;color:var(--qz-ink-soft);font-weight:600;">'+cell+'</span>';
              html += '</td>';
            } else {
              html += '<td style="padding:8px 14px;border-bottom:1px solid var(--qz-border-soft);'+(ci===0?'font-weight:600;color:var(--qz-ink-soft);':'color:var(--qz-ink-soft);')+'">'+cell+'</td>';
            }
          });
          html += '</tr>';
        });
        html += '</tbody></table></div>';
        return html;
      }

      function parseChartValue(s){
        return parseFloat(s.replace(/[£$,%m]/g,''));
      }

      function niceTicks(maxVal, targetTicks){
        targetTicks = targetTicks || 5;
        if(maxVal <= 0) return {ticks:[0], max:1};
        var roughStep = maxVal / targetTicks;
        var magnitude = Math.pow(10, Math.floor(Math.log10(roughStep)));
        var normalized = roughStep / magnitude;
        var niceStep;
        if(normalized < 1.5) niceStep = 1;
        else if(normalized < 3) niceStep = 2;
        else if(normalized < 7) niceStep = 5;
        else niceStep = 10;
        niceStep *= magnitude;
        var niceMax = Math.ceil(maxVal / niceStep) * niceStep;
        var ticks = [];
        for(var v=0; v<=niceMax+0.0001; v+=niceStep){ ticks.push(Math.round(v*100)/100); }
        return {ticks:ticks, max:niceMax};
      }

      // ============ RESTYLED "SCIENTIFIC" CHART FUNCTIONS - PILOT (Q5 scatter, Q7 stacked-bar, Q12/Q16 line) ============
      // Shared style constants
      var QZ_DARK = document.documentElement.getAttribute('data-theme') === 'dark';
      var SCI_FONT = "Arial, Helvetica, sans-serif";
      var SCI_GRID = QZ_DARK ? "rgba(255,255,255,0.16)" : "#bbbbbb";      // gridline color
      var SCI_AXIS = QZ_DARK ? "rgba(245,241,233,0.55)" : "#333333";      // axis line / border color
      var SCI_TEXT = QZ_DARK ? "#f5f1e9" : "#333333";      // label text color
      var SCI_SINGLE = QZ_DARK ? "#e2725c" : "#8b2020";    // single-series plain color
      var SCI_PALETTE = QZ_DARK ? ["#7fa8e0","#e2725c","#c9b45a","#b7b7bd"] : ["#1a3a6b","#8b2020","#5a5a2a","#555555"]; // multi-series
      var SCI_PIE_PALETTE = QZ_DARK ? ["#7fa8e0","#e2725c","#c9b45a","#b7b7bd","#5fbdbd","#8A4523"] : ["#1a3a6b","#8b2020","#5a5a2a","#555555","#2a5a5a","#6b4a2a"]; // extended for pie


      // ---- Q7: buildStackedBarHTML (restyled) ----
      function buildStackedBarHTML(table){
        if(!table) return '';
        var seriesNames = table.headers.slice(1);
        var categories = table.rows.map(function(r){ return r[0]; });
        var colors = SCI_PALETTE;
        var w=520, h=250, padL=54, padR=20, padT=16, padB=44;
        var plotH = h-padT-padB, plotW = w-padL-padR;
        var parsedRows = table.rows.map(function(r){ return r.slice(1).map(parseChartValue); });
        var totals = parsedRows.map(function(vals){ return vals.reduce(function(a,b){ return a+b; },0); });
        var maxTotal = Math.max.apply(null, totals);
        var nt = niceTicks(maxTotal, 5);
        function yFor(v){ return padT + plotH - (plotH*(v/nt.max)); }
        var n = categories.length;
        var slotW = plotW/n;
        var barW = Math.min(70, slotW*0.55);
        var svg = '<svg viewBox="0 0 '+w+' '+h+'" style="width:100%;height:250px;display:block;">';
        svg += '<rect x="'+padL+'" y="'+padT+'" width="'+plotW+'" height="'+plotH+'" fill="none" stroke="'+SCI_AXIS+'" stroke-width="1"/>';
        nt.ticks.forEach(function(t){
          var y = yFor(t);
          svg += '<line x1="'+padL+'" y1="'+y.toFixed(1)+'" x2="'+(w-padR)+'" y2="'+y.toFixed(1)+'" stroke="'+SCI_GRID+'" stroke-width="1"/>';
          svg += '<text x="'+(padL-8)+'" y="'+(y+3.5).toFixed(1)+'" text-anchor="end" font-size="10.5" fill="'+SCI_TEXT+'" font-family="'+SCI_FONT+'">'+t+'</text>';
        });
        categories.forEach(function(cat,ci){
          var cx = padL + slotW*(ci+0.5);
          var cumulative = 0;
          parsedRows[ci].forEach(function(val, si){
            var segBottom = yFor(cumulative);
            var segTop = yFor(cumulative+val);
            svg += '<rect x="'+(cx-barW/2).toFixed(1)+'" y="'+segTop.toFixed(1)+'" width="'+barW.toFixed(1)+'" height="'+(segBottom-segTop).toFixed(1)+'" fill="'+colors[si%colors.length]+'" stroke="'+SCI_AXIS+'" stroke-width="0.75"/>';
            cumulative += val;
          });
          svg += '<text x="'+cx.toFixed(1)+'" y="'+(h-14)+'" text-anchor="middle" font-size="11" fill="'+SCI_TEXT+'" font-family="'+SCI_FONT+'">'+cat+'</text>';
        });
        svg += '<text x="'+(padL+plotW/2)+'" y="'+(h-2)+'" text-anchor="middle" font-size="11" fill="'+SCI_TEXT+'" font-family="'+SCI_FONT+'">year</text>';
        svg += '<text x="14" y="'+(padT+plotH/2)+'" text-anchor="middle" font-size="11" fill="'+SCI_TEXT+'" font-family="'+SCI_FONT+'" transform="rotate(-90 14 '+(padT+plotH/2)+')">£m</text>';
        svg += '</svg>';
        var legend = '<div style="display:flex;gap:16px;flex-wrap:wrap;margin-top:8px;justify-content:center;font-family:'+SCI_FONT+';">';
        seriesNames.forEach(function(sn,si){
          legend += '<div style="display:flex;align-items:center;gap:6px;font-size:12px;color:'+SCI_TEXT+';"><div style="width:11px;height:11px;background:'+colors[si%colors.length]+';border:1px solid '+SCI_AXIS+';"></div>'+sn+'</div>';
        });
        legend += '</div>';
        return '<div style="margin:14px 0;padding:16px;border:1px solid '+SCI_AXIS+';border-radius:0;background:var(--qz-bg);">'+svg+legend+'</div>';
      }

      // ---- Q12/Q16: buildLineChartHTML (restyled) ----
      function buildLineChartHTML(table){
        if(!table) return '';
        var isMultiSeries = table.headers.length > 2;
        var colors = SCI_PALETTE;
        var w=560, h=240, padX=54, padT=16, padB=44;
        var svg;
        if(!isMultiSeries){
          var pts = table.rows.map(function(r){ return {label:r[0], display:r[1], value:parseChartValue(r[1])}; });
          var vals = pts.map(function(p){ return p.value; });
          var maxVal = Math.max.apply(null, vals);
          var nt = niceTicks(maxVal, 5);
          var plotH = h-padT-padB, plotW = w-2*padX;
          function yFor(v){ return padT + plotH - (plotH*(v/nt.max)); }
          var n = pts.length;
          var coords = pts.map(function(p,i){
            var x = padX + plotW * (n>1 ? i/(n-1) : 0.5);
            return {x:x, y:yFor(p.value), label:p.label, display:p.display};
          });
          var pathD = coords.map(function(c,i){ return (i===0?'M':'L')+c.x.toFixed(1)+','+c.y.toFixed(1); }).join(' ');
          svg = '<svg viewBox="0 0 '+w+' '+h+'" style="width:100%;height:240px;display:block;">';
          svg += '<rect x="'+padX+'" y="'+padT+'" width="'+plotW+'" height="'+plotH+'" fill="none" stroke="'+SCI_AXIS+'" stroke-width="1"/>';
          nt.ticks.forEach(function(t){
            var y = yFor(t);
            svg += '<line x1="'+padX+'" y1="'+y.toFixed(1)+'" x2="'+(w-padX)+'" y2="'+y.toFixed(1)+'" stroke="'+SCI_GRID+'" stroke-width="1"/>';
            svg += '<text x="'+(padX-8)+'" y="'+(y+3.5).toFixed(1)+'" text-anchor="end" font-size="10.5" fill="'+SCI_TEXT+'" font-family="'+SCI_FONT+'">'+t+'</text>';
          });
          svg += '<path d="'+pathD+'" fill="none" stroke="'+SCI_SINGLE+'" stroke-width="1.75"/>';
          coords.forEach(function(c){
            svg += '<circle cx="'+c.x.toFixed(1)+'" cy="'+c.y.toFixed(1)+'" r="3.5" fill="'+SCI_SINGLE+'" stroke="'+SCI_AXIS+'" stroke-width="0.5"/>';
            svg += '<text x="'+c.x.toFixed(1)+'" y="'+(h-14)+'" text-anchor="middle" font-size="11" fill="'+SCI_TEXT+'" font-family="'+SCI_FONT+'">'+c.label+'</text>';
          });
          svg += '</svg>';
          return '<div style="margin:14px 0;padding:16px;border:1px solid '+SCI_AXIS+';border-radius:0;background:var(--qz-bg);">'+svg+'</div>';
        }
        var periods = table.headers.slice(1);
        var series = table.rows.map(function(r){ return {name:r[0], values:r.slice(1).map(parseChartValue), display:r.slice(1)}; });
        var allVals = [];
        series.forEach(function(s){ allVals = allVals.concat(s.values); });
        var maxVal = Math.max.apply(null, allVals);
        var nt = niceTicks(maxVal, 5);
        var plotH = h-padT-padB, plotW = w-2*padX;
        function yFor2(v){ return padT + plotH - (plotH*(v/nt.max)); }
        var np = periods.length;
        svg = '<svg viewBox="0 0 '+w+' '+h+'" style="width:100%;height:240px;display:block;">';
        svg += '<rect x="'+padX+'" y="'+padT+'" width="'+plotW+'" height="'+plotH+'" fill="none" stroke="'+SCI_AXIS+'" stroke-width="1"/>';
        nt.ticks.forEach(function(t){
          var y = yFor2(t);
          svg += '<line x1="'+padX+'" y1="'+y.toFixed(1)+'" x2="'+(w-padX)+'" y2="'+y.toFixed(1)+'" stroke="'+SCI_GRID+'" stroke-width="1"/>';
          svg += '<text x="'+(padX-8)+'" y="'+(y+3.5).toFixed(1)+'" text-anchor="end" font-size="10.5" fill="'+SCI_TEXT+'" font-family="'+SCI_FONT+'">'+t+'</text>';
        });
        series.forEach(function(s, si){
          var coords = s.values.map(function(v,i){
            var x = padX + plotW * (np>1 ? i/(np-1) : 0.5);
            return {x:x, y:yFor2(v)};
          });
          var pathD = coords.map(function(c,i){ return (i===0?'M':'L')+c.x.toFixed(1)+','+c.y.toFixed(1); }).join(' ');
          svg += '<path d="'+pathD+'" fill="none" stroke="'+colors[si%colors.length]+'" stroke-width="1.75"/>';
          coords.forEach(function(c){ svg += '<circle cx="'+c.x.toFixed(1)+'" cy="'+c.y.toFixed(1)+'" r="3" fill="'+colors[si%colors.length]+'" stroke="'+SCI_AXIS+'" stroke-width="0.5"/>'; });
        });
        periods.forEach(function(p,i){
          var x = padX + plotW * (np>1 ? i/(np-1) : 0.5);
          svg += '<text x="'+x.toFixed(1)+'" y="'+(h-14)+'" text-anchor="middle" font-size="11" fill="'+SCI_TEXT+'" font-family="'+SCI_FONT+'">'+p+'</text>';
        });
        svg += '</svg>';
        var legend = '<div style="display:flex;gap:16px;flex-wrap:wrap;margin-top:8px;justify-content:center;font-family:'+SCI_FONT+';">';
        series.forEach(function(s,si){
          legend += '<div style="display:flex;align-items:center;gap:6px;font-size:12px;color:'+SCI_TEXT+';"><div style="width:14px;height:2px;background:'+colors[si%colors.length]+';"></div>'+s.name+'</div>';
        });
        legend += '</div>';
        return '<div style="margin:14px 0;padding:16px;border:1px solid '+SCI_AXIS+';border-radius:0;background:var(--qz-bg);">'+svg+legend+'</div>';
      }

      // ---- Q5: buildScatterChartHTML (restyled) ----
      function buildScatterChartHTML(table){
        if(!table) return '';
        var pts = table.rows.map(function(r){ return {label:r[0], xDisplay:r[1], yDisplay:r[2], x:parseChartValue(r[1]), y:parseChartValue(r[2])}; });
        var xs = pts.map(function(p){ return p.x; }), ys = pts.map(function(p){ return p.y; });
        var xHi = Math.max.apply(null,xs);
        var yHi = Math.max.apply(null,ys);
        var ntX = niceTicks(xHi*1.1, 5);
        var ntY = niceTicks(yHi*1.1, 5);
        var w=420, h=330, padL=54, padR=24, padT=20, padB=54;
        var plotW = w-padL-padR, plotH = h-padT-padB;
        function px(v){ return padL + plotW * (v/ntX.max); }
        function py(v){ return (h-padB) - plotH * (v/ntY.max); }
        var svg = '<svg viewBox="0 0 '+w+' '+h+'" style="width:100%;max-width:440px;height:330px;display:block;">';
        svg += '<rect x="'+padL+'" y="'+padT+'" width="'+plotW+'" height="'+plotH+'" fill="none" stroke="'+SCI_AXIS+'" stroke-width="1"/>';
        ntY.ticks.forEach(function(t){
          var y = py(t);
          svg += '<line x1="'+padL+'" y1="'+y.toFixed(1)+'" x2="'+(w-padR)+'" y2="'+y.toFixed(1)+'" stroke="'+SCI_GRID+'" stroke-width="1"/>';
          svg += '<text x="'+(padL-8)+'" y="'+(y+3.5).toFixed(1)+'" text-anchor="end" font-size="10" fill="'+SCI_TEXT+'" font-family="'+SCI_FONT+'">'+t+'</text>';
        });
        ntX.ticks.forEach(function(t){
          var x = px(t);
          svg += '<line x1="'+x.toFixed(1)+'" y1="'+padT+'" x2="'+x.toFixed(1)+'" y2="'+(h-padB)+'" stroke="'+SCI_GRID+'" stroke-width="1"/>';
          svg += '<text x="'+x.toFixed(1)+'" y="'+(h-padB+16)+'" text-anchor="middle" font-size="10" fill="'+SCI_TEXT+'" font-family="'+SCI_FONT+'">'+t+'</text>';
        });
        pts.forEach(function(p){
          var cx = px(p.x), cy = py(p.y);
          svg += '<circle cx="'+cx.toFixed(1)+'" cy="'+cy.toFixed(1)+'" r="4.5" fill="'+SCI_SINGLE+'" stroke="'+SCI_AXIS+'" stroke-width="0.75"/>';
          svg += '<text x="'+cx.toFixed(1)+'" y="'+(cy-9).toFixed(1)+'" text-anchor="middle" font-size="11" fill="'+SCI_TEXT+'" font-family="'+SCI_FONT+'">'+p.label+'</text>';
        });
        svg += '<text x="'+(padL+plotW/2)+'" y="'+(h-10)+'" text-anchor="middle" font-size="11" fill="'+SCI_TEXT+'" font-family="'+SCI_FONT+'">'+(table.headers[1]||'x').toLowerCase()+'</text>';
        svg += '<text x="14" y="'+(padT+plotH/2)+'" text-anchor="middle" font-size="11" fill="'+SCI_TEXT+'" font-family="'+SCI_FONT+'" transform="rotate(-90 14 '+(padT+plotH/2)+')">'+(table.headers[2]||'y').toLowerCase()+'</text>';
        svg += '</svg>';
        return '<div style="margin:14px 0;padding:16px;border:1px solid '+SCI_AXIS+';border-radius:0;background:var(--qz-bg);">'+svg+'</div>';
      }

      // ---- buildBarChartHTML (restyled) ----
      function buildBarChartHTML(table){
        if(!table) return '';
        var isMultiSeries = table.headers.length > 2;
        var colors = SCI_PALETTE;
        var w=520, h=240, padL=50, padR=16, padT=16, padB=44;
        var plotH = h-padT-padB, plotW = w-padL-padR;
        if(!isMultiSeries){
          var pts = table.rows.map(function(r){ return {label:r[0], display:r[1], value:parseChartValue(r[1])}; });
          var maxVal = Math.max.apply(null, pts.map(function(p){ return p.value; }));
          var unitMatch = pts[0].display.match(/^([£$]?)(-?[\d,.]+)(.*)/);
          var unitPrefix = unitMatch ? unitMatch[1] : '';
          var unitSuffix = unitMatch ? unitMatch[3] : '';
          var nt = niceTicks(maxVal, 5);
          function yFor(v){ return padT + plotH - (plotH * (v/nt.max)); }
          var n = pts.length;
          var slotW = plotW/n;
          var svg = '<svg viewBox="0 0 '+w+' '+h+'" style="width:100%;height:240px;display:block;">';
          svg += '<rect x="'+padL+'" y="'+padT+'" width="'+plotW+'" height="'+plotH+'" fill="none" stroke="'+SCI_AXIS+'" stroke-width="1"/>';
          nt.ticks.forEach(function(t){
            var y = yFor(t);
            svg += '<line x1="'+padL+'" y1="'+y.toFixed(1)+'" x2="'+(w-padR)+'" y2="'+y.toFixed(1)+'" stroke="'+SCI_GRID+'" stroke-width="1"/>';
            svg += '<text x="'+(padL-8)+'" y="'+(y+3.5).toFixed(1)+'" text-anchor="end" font-size="10.5" fill="'+SCI_TEXT+'" font-family="'+SCI_FONT+'">'+unitPrefix+t+unitSuffix+'</text>';
          });
          pts.forEach(function(p,i){
            var barW = Math.min(52, slotW*0.55);
            var cx = padL + slotW*(i+0.5);
            var barTop = yFor(p.value);
            var barBottom = yFor(0);
            svg += '<rect x="'+(cx-barW/2).toFixed(1)+'" y="'+barTop.toFixed(1)+'" width="'+barW.toFixed(1)+'" height="'+(barBottom-barTop).toFixed(1)+'" fill="'+SCI_SINGLE+'" stroke="'+SCI_AXIS+'" stroke-width="0.75"/>';
            if(!table.hideLabels){
              svg += '<text x="'+cx.toFixed(1)+'" y="'+(barTop-8).toFixed(1)+'" text-anchor="middle" font-size="11" fill="'+SCI_TEXT+'" font-family="'+SCI_FONT+'">'+p.display+'</text>';
            }
            svg += '<text x="'+cx.toFixed(1)+'" y="'+(h-14)+'" text-anchor="middle" font-size="11" fill="'+SCI_TEXT+'" font-family="'+SCI_FONT+'">'+p.label+'</text>';
          });
          svg += '</svg>';
          return '<div style="margin:14px 0;padding:16px;border:1px solid '+SCI_AXIS+';border-radius:0;background:var(--qz-bg);">'+svg+'</div>';
        }
        var seriesNames = table.headers.slice(1);
        var categories = table.rows.map(function(r){ return r[0]; });
        var nSeries = seriesNames.length;
        var allVals = [];
        table.rows.forEach(function(r){ r.slice(1).forEach(function(v){ allVals.push(parseChartValue(v)); }); });
        var maxVal = Math.max.apply(null, allVals);
        var nt = niceTicks(maxVal, 5);
        function yFor2(v){ return padT + plotH - (plotH*(v/nt.max)); }
        var n = categories.length;
        var slotW = plotW/n;
        var groupW = Math.min(slotW*0.7, 60);
        var barW = groupW/nSeries;
        var svg = '<svg viewBox="0 0 '+w+' '+h+'" style="width:100%;height:240px;display:block;">';
        svg += '<rect x="'+padL+'" y="'+padT+'" width="'+plotW+'" height="'+plotH+'" fill="none" stroke="'+SCI_AXIS+'" stroke-width="1"/>';
        nt.ticks.forEach(function(t){
          var y = yFor2(t);
          svg += '<line x1="'+padL+'" y1="'+y.toFixed(1)+'" x2="'+(w-padR)+'" y2="'+y.toFixed(1)+'" stroke="'+SCI_GRID+'" stroke-width="1"/>';
          svg += '<text x="'+(padL-8)+'" y="'+(y+3.5).toFixed(1)+'" text-anchor="end" font-size="10.5" fill="'+SCI_TEXT+'" font-family="'+SCI_FONT+'">'+t+'</text>';
        });
        categories.forEach(function(cat,ci){
          var groupCx = padL + slotW*(ci+0.5);
          var groupLeft = groupCx - groupW/2;
          seriesNames.forEach(function(sn,si){
            var val = parseChartValue(table.rows[ci][si+1]);
            var barTop = yFor2(val);
            var barBottom = yFor2(0);
            var bx = groupLeft + si*barW;
            svg += '<rect x="'+bx.toFixed(1)+'" y="'+barTop.toFixed(1)+'" width="'+(barW*0.85).toFixed(1)+'" height="'+(barBottom-barTop).toFixed(1)+'" fill="'+colors[si%colors.length]+'" stroke="'+SCI_AXIS+'" stroke-width="0.75"/>';
          });
          svg += '<text x="'+groupCx.toFixed(1)+'" y="'+(h-14)+'" text-anchor="middle" font-size="11" fill="'+SCI_TEXT+'" font-family="'+SCI_FONT+'">'+cat+'</text>';
        });
        svg += '</svg>';
        var legend = '<div style="display:flex;gap:16px;flex-wrap:wrap;margin-top:8px;justify-content:center;font-family:'+SCI_FONT+';">';
        seriesNames.forEach(function(sn,si){
          legend += '<div style="display:flex;align-items:center;gap:6px;font-size:12px;color:'+SCI_TEXT+';"><div style="width:11px;height:11px;background:'+colors[si%colors.length]+';border:1px solid '+SCI_AXIS+';"></div>'+sn+'</div>';
        });
        legend += '</div>';
        return '<div style="margin:14px 0;padding:16px;border:1px solid '+SCI_AXIS+';border-radius:0;background:var(--qz-bg);">'+svg+legend+'</div>';
      }

      // ---- buildHorizontalBarHTML (restyled) ----
      function buildHorizontalBarHTML(table){
        if(!table) return '';
        var pts = table.rows.map(function(r){ return {label:r[0], display:r[r.length-1], value:parseChartValue(r[r.length-1])}; });
        var maxVal = Math.max.apply(null, pts.map(function(p){ return p.value; }));
        var unitMatch = pts[0].display.match(/^([£$]?)(-?[\d,.]+)(.*)/);
        var unitPrefix = unitMatch ? unitMatch[1] : '';
        var unitSuffix = unitMatch ? unitMatch[3] : '';
        var nt = niceTicks(maxVal, 5);
        var n = pts.length;
        var w=520, h=44*n+40, padL=64, padR=20, padT=10, padB=30;
        var plotW = w-padL-padR, plotH = h-padT-padB;
        function xFor(v){ return padL + plotW*(v/nt.max); }
        var svg = '<svg viewBox="0 0 '+w+' '+h+'" style="width:100%;height:'+h+'px;display:block;">';
        svg += '<rect x="'+padL+'" y="'+padT+'" width="'+plotW+'" height="'+plotH+'" fill="none" stroke="'+SCI_AXIS+'" stroke-width="1"/>';
        nt.ticks.forEach(function(t){
          var x = xFor(t);
          svg += '<line x1="'+x.toFixed(1)+'" y1="'+padT+'" x2="'+x.toFixed(1)+'" y2="'+(h-padB)+'" stroke="'+SCI_GRID+'" stroke-width="1"/>';
          svg += '<text x="'+x.toFixed(1)+'" y="'+(h-padB+16)+'" text-anchor="middle" font-size="10" fill="'+SCI_TEXT+'" font-family="'+SCI_FONT+'">'+unitPrefix+t+unitSuffix+'</text>';
        });
        pts.forEach(function(p,i){
          var barY = padT + i*44 + 8;
          var barH = 22;
          var barEnd = xFor(p.value);
          svg += '<text x="'+(padL-8)+'" y="'+(barY+barH/2+4)+'" text-anchor="end" font-size="12" fill="'+SCI_TEXT+'" font-family="'+SCI_FONT+'">'+p.label+'</text>';
          svg += '<rect x="'+padL+'" y="'+barY+'" width="'+(barEnd-padL).toFixed(1)+'" height="'+barH+'" fill="'+SCI_SINGLE+'" stroke="'+SCI_AXIS+'" stroke-width="0.75"/>';
          if(!table.hideLabels){
            svg += '<text x="'+(barEnd+6).toFixed(1)+'" y="'+(barY+barH/2+4)+'" font-size="12" fill="'+SCI_TEXT+'" font-family="'+SCI_FONT+'">'+p.display+'</text>';
          }
        });
        svg += '</svg>';
        return '<div style="margin:14px 0;padding:16px;border:1px solid '+SCI_AXIS+';border-radius:0;background:var(--qz-bg);">'+svg+'</div>';
      }

      // ---- buildPieChartHTML (restyled) ----
      function buildPieChartHTML(table){
        if(!table) return '';
        var colors = SCI_PIE_PALETTE;
        var pts = table.rows.map(function(r){ return {label:r[0], display:r[1], value:parseChartValue(r[1])}; });
        var total = pts.reduce(function(s,p){ return s+p.value; }, 0);
        var cx=90, cy=90, r=78;
        var svg = '<svg viewBox="0 0 180 180" style="width:180px;height:180px;flex-shrink:0;">';
        svg += '<circle cx="'+cx+'" cy="'+cy+'" r="'+r+'" fill="none" stroke="'+SCI_AXIS+'" stroke-width="1"/>';
        var angle = 0;
        pts.forEach(function(p,i){
          var slice = (p.value/total) * Math.PI * 2;
          var startA = angle, endA = angle + slice;
          var x1 = cx + r*Math.sin(startA), y1 = cy - r*Math.cos(startA);
          var x2 = cx + r*Math.sin(endA), y2 = cy - r*Math.cos(endA);
          var largeArc = slice > Math.PI ? 1 : 0;
          var d = 'M'+cx+','+cy+' L'+x1.toFixed(1)+','+y1.toFixed(1)+' A'+r+','+r+' 0 '+largeArc+',1 '+x2.toFixed(1)+','+y2.toFixed(1)+' Z';
          svg += '<path d="'+d+'" fill="'+colors[i%colors.length]+'" stroke="'+SCI_AXIS+'" stroke-width="1"/>';
          angle = endA;
        });
        svg += '</svg>';
        var legend = '<div style="display:flex;flex-direction:column;gap:8px;justify-content:center;font-family:'+SCI_FONT+';">';
        pts.forEach(function(p,i){
          legend += '<div style="display:flex;align-items:center;gap:8px;font-size:12.5px;">';
          legend += '<div style="width:11px;height:11px;background:'+colors[i%colors.length]+';border:1px solid '+SCI_AXIS+';flex-shrink:0;"></div>';
          legend += '<div style="color:'+SCI_TEXT+';">'+p.label+'</div><div style="color:'+SCI_TEXT+';">'+p.display+'</div>';
          legend += '</div>';
        });
        legend += '</div>';
        return '<div style="margin:14px 0;padding:16px;border:1px solid '+SCI_AXIS+';border-radius:0;background:var(--qz-bg);display:flex;gap:20px;align-items:center;flex-wrap:wrap;">'+svg+legend+'</div>';
      }

      // ---- buildBubbleChartHTML (restyled) ----
      function buildBubbleChartHTML(table){
        if(!table) return '';
        var pts = table.rows.map(function(r){ return {label:r[0], amountDisplay:r[1], returnDisplay:r[2], amount:parseChartValue(r[1]), ret:parseChartValue(r[2])}; });
        var amounts = pts.map(function(p){ return p.amount; });
        var maxAmount = Math.max.apply(null, amounts), minAmount = Math.min.apply(null, amounts);
        var rets = pts.map(function(p){ return p.ret; });
        var minRet=Math.min.apply(null,rets), maxRet=Math.max.apply(null,rets);
        var loRet = Math.max(0, minRet - (maxRet-minRet||1)*0.3);
        var nt = niceTicks(maxRet + (maxRet-minRet||1)*0.3 - loRet, 4);
        var axisMax = loRet + nt.max;
        var w=400, h=220, padL=34, padR=34, padB=50, midY=86;
        function xFor(v){ return padL + (w-padL-padR)*((v-loRet)/(axisMax-loRet)); }
        var coords = pts.map(function(p){
          var sizeNorm = maxAmount>minAmount ? (p.amount-minAmount)/(maxAmount-minAmount) : 0.5;
          var r = 16 + sizeNorm*20;
          return {x:xFor(p.ret), y:midY, r:r, returnDisplay:p.returnDisplay, amountDisplay:p.amountDisplay, label:p.label};
        });
        var svg = '<svg viewBox="0 0 '+w+' '+h+'" style="width:100%;max-width:420px;height:220px;display:block;">';
        var axisY = midY+50;
        svg += '<rect x="'+padL+'" y="'+(midY-42)+'" width="'+(w-padL-padR)+'" height="'+(axisY-(midY-42))+'" fill="none" stroke="'+SCI_AXIS+'" stroke-width="1"/>';
        nt.ticks.forEach(function(t){
          var v = loRet+t;
          var x = xFor(v);
          svg += '<line x1="'+x.toFixed(1)+'" y1="'+(midY-42)+'" x2="'+x.toFixed(1)+'" y2="'+axisY+'" stroke="'+SCI_GRID+'" stroke-width="1"/>';
          svg += '<text x="'+x.toFixed(1)+'" y="'+(axisY+14)+'" text-anchor="middle" font-size="10" fill="'+SCI_TEXT+'" font-family="'+SCI_FONT+'">'+Math.round(v)+'%</text>';
        });
        coords.forEach(function(c){
          svg += '<circle cx="'+c.x.toFixed(1)+'" cy="'+c.y.toFixed(1)+'" r="'+c.r.toFixed(1)+'" fill="'+SCI_SINGLE+'" fill-opacity="0.35" stroke="'+SCI_AXIS+'" stroke-width="1"/>';
          svg += '<text x="'+c.x.toFixed(1)+'" y="'+c.y.toFixed(1)+'" text-anchor="middle" dy="0.35em" font-size="11" fill="'+SCI_TEXT+'" font-family="'+SCI_FONT+'">'+c.returnDisplay+'</text>';
        });
        svg += '<text x="'+(w/2)+'" y="'+(h-8)+'" text-anchor="middle" font-size="11" fill="'+SCI_TEXT+'" font-family="'+SCI_FONT+'">'+(table.headers[2]||'return').toLowerCase()+' (bubble size = '+(table.headers[1]||'amount').toLowerCase()+')</text>';
        svg += '</svg>';
        var legend = '<div style="display:flex;gap:16px;flex-wrap:wrap;margin-top:6px;justify-content:center;font-family:'+SCI_FONT+';">';
        pts.forEach(function(p){ legend += '<div style="font-size:11.5px;color:'+SCI_TEXT+';">'+p.label+': '+p.amountDisplay+' at '+p.returnDisplay+'</div>'; });
        legend += '</div>';
        return '<div style="margin:14px 0;padding:16px;border:1px solid '+SCI_AXIS+';border-radius:0;background:var(--qz-bg);">'+svg+legend+'</div>';
      }



      // Nice-tick helper that supports an arbitrary (possibly negative) minimum -
      // the local niceTicks(maxVal, targetTicks) above always starts at 0, which
      // breaks for data that crosses zero (e.g. a bubble chart's growth-rate axis).
      function niceTicksRange(min, max, count){
        var range = max - min || 1;
        var rawStep = range / (count - 1);
        var mag = Math.pow(10, Math.floor(Math.log10(rawStep)));
        var residual = rawStep / mag;
        var niceStep;
        if(residual > 5) niceStep = 10 * mag;
        else if(residual > 2) niceStep = 5 * mag;
        else if(residual > 1) niceStep = 2 * mag;
        else niceStep = mag;
        var niceMin = Math.ceil(min / niceStep) * niceStep;
        var ticks = [];
        for(var v = niceMin; v <= max + 1e-9; v += niceStep){ ticks.push(Math.round(v * 1000) / 1000); }
        return ticks;
      }

      // ---- buildComboChartHTML: revenue/volume bars + a second metric (e.g. margin %)
      // plotted as a line on its own scale, for dual-axis exhibits. table.headers =
      // [CategoryLabel, BarSeriesName, LineSeriesName]; table.rows = [[cat, barVal, lineVal], ...] ----
      function buildComboChartHTML(table){
        if(!table) return '';
        var barName = table.headers[1] || 'Value', lineName = table.headers[2] || 'Rate';
        var pts = table.rows.map(function(r){ return {label:r[0], barDisplay:r[1], lineDisplay:r[2], barVal:parseChartValue(r[1]), lineVal:parseChartValue(r[2])}; });
        var barMax = Math.max.apply(null, pts.map(function(p){ return p.barVal; }), 0);
        var lineVals = pts.map(function(p){ return p.lineVal; });
        var lineMin = Math.min.apply(null, lineVals.concat([0]));
        var lineMax = Math.max.apply(null, lineVals.concat([0]));
        var ntBar = niceTicks(barMax, 5);
        var lineTicks = niceTicksRange(lineMin, lineMax + (lineMax-lineMin||1)*0.15, 5);
        var lineAxisMax = Math.max(lineMax + (lineMax-lineMin||1)*0.15, lineTicks.length ? lineTicks[lineTicks.length-1] : lineMax);
        var lineAxisMin = Math.min(lineMin, lineTicks.length ? lineTicks[0] : lineMin);
        var w=560, h=280, padL=54, padR=54, padT=20, padB=44;
        var plotW = w-padL-padR, plotH = h-padT-padB;
        var n = pts.length;
        var slotW = plotW/n;
        function yBar(v){ return padT + plotH - (plotH*(v/(ntBar.max||1))); }
        function yLine(v){ return padT + plotH - (plotH*((v-lineAxisMin)/((lineAxisMax-lineAxisMin)||1))); }
        function xCenter(i){ return padL + slotW*(i+0.5); }
        var svg = '<svg viewBox="0 0 '+w+' '+h+'" style="width:100%;height:280px;display:block;">';
        svg += '<rect x="'+padL+'" y="'+padT+'" width="'+plotW+'" height="'+plotH+'" fill="none" stroke="'+SCI_AXIS+'" stroke-width="1"/>';
        ntBar.ticks.forEach(function(t){
          var y = yBar(t);
          svg += '<line x1="'+padL+'" y1="'+y.toFixed(1)+'" x2="'+(w-padR)+'" y2="'+y.toFixed(1)+'" stroke="'+SCI_GRID+'" stroke-width="1"/>';
          svg += '<text x="'+(padL-8)+'" y="'+(y+3.5).toFixed(1)+'" text-anchor="end" font-size="10" fill="'+SCI_TEXT+'" font-family="'+SCI_FONT+'">'+t+'</text>';
        });
        lineTicks.forEach(function(t){
          var y = yLine(t);
          svg += '<text x="'+(w-padR+8)+'" y="'+(y+3.5).toFixed(1)+'" text-anchor="start" font-size="10" fill="'+SCI_PALETTE[1]+'" font-family="'+SCI_FONT+'">'+t+'%</text>';
        });
        pts.forEach(function(p,i){
          var barW = Math.min(52, slotW*0.5);
          var cx = xCenter(i);
          var barTop = yBar(p.barVal), barBottom = yBar(0);
          svg += '<rect x="'+(cx-barW/2).toFixed(1)+'" y="'+barTop.toFixed(1)+'" width="'+barW.toFixed(1)+'" height="'+(barBottom-barTop).toFixed(1)+'" fill="'+SCI_PALETTE[0]+'" stroke="'+SCI_AXIS+'" stroke-width="0.75"/>';
          svg += '<text x="'+cx.toFixed(1)+'" y="'+(h-14)+'" text-anchor="middle" font-size="11" fill="'+SCI_TEXT+'" font-family="'+SCI_FONT+'">'+p.label+'</text>';
        });
        var linePath = pts.map(function(p,i){ return (i===0?'M':'L')+xCenter(i).toFixed(1)+','+yLine(p.lineVal).toFixed(1); }).join(' ');
        if(n>1){ svg += '<path d="'+linePath+'" fill="none" stroke="'+SCI_PALETTE[1]+'" stroke-width="1.75"/>'; }
        pts.forEach(function(p,i){
          var cx = xCenter(i), cy = yLine(p.lineVal);
          var label = p.lineDisplay;
          var pillW = Math.max(28, label.length*6.4+10), pillH=16;
          svg += '<circle cx="'+cx.toFixed(1)+'" cy="'+cy.toFixed(1)+'" r="4" fill="'+SCI_PALETTE[1]+'" stroke="'+SCI_AXIS+'" stroke-width="0.75"/>';
          var pillY = cy-11-pillH;
          if(pillY < padT-4) pillY = cy+11;
          svg += '<rect x="'+(cx-pillW/2).toFixed(1)+'" y="'+pillY.toFixed(1)+'" width="'+pillW.toFixed(1)+'" height="'+pillH+'" rx="7" fill="var(--qz-bg)" stroke="'+SCI_AXIS+'" stroke-width="0.75"/>';
          svg += '<text x="'+cx.toFixed(1)+'" y="'+(pillY+11.5).toFixed(1)+'" text-anchor="middle" font-size="10.5" font-weight="700" fill="'+SCI_PALETTE[1]+'" font-family="'+SCI_FONT+'">'+label+'</text>';
        });
        svg += '</svg>';
        var legend = '<div style="display:flex;gap:16px;flex-wrap:wrap;margin-top:8px;justify-content:center;font-family:'+SCI_FONT+';">';
        legend += '<div style="display:flex;align-items:center;gap:6px;font-size:12px;color:'+SCI_TEXT+';"><div style="width:11px;height:11px;background:'+SCI_PALETTE[0]+';border:1px solid '+SCI_AXIS+';"></div>'+barName+' (left axis)</div>';
        legend += '<div style="display:flex;align-items:center;gap:6px;font-size:12px;color:'+SCI_TEXT+';"><div style="width:14px;height:2px;background:'+SCI_PALETTE[1]+';"></div>'+lineName+' (right axis)</div>';
        legend += '</div>';
        return '<div style="margin:14px 0;padding:16px;border:1px solid '+SCI_AXIS+';border-radius:0;background:var(--qz-bg);">'+svg+legend+'</div>';
      }

      // ---- buildBubbleXYChartHTML: a genuine two-axis bubble chart (x, y, and size all
      // independent). table.headers = [Label, XAxisName, YAxisName, SizeName];
      // table.rows = [[label, xVal, yVal, sizeVal], ...] ----
      function buildBubbleXYChartHTML(table){
        if(!table) return '';
        var xName = table.headers[1] || 'x', yName = table.headers[2] || 'y', sizeName = table.headers[3] || 'size';
        var pts = table.rows.map(function(r){ return {label:r[0], xDisplay:r[1], yDisplay:r[2], sizeDisplay:r[3], x:parseChartValue(r[1]), y:parseChartValue(r[2]), size:parseChartValue(r[3])}; });
        var xs = pts.map(function(p){ return p.x; }), ys = pts.map(function(p){ return p.y; }), sizes = pts.map(function(p){ return p.size; });
        var xMin=Math.min.apply(null,xs), xMax=Math.max.apply(null,xs);
        var yMin=Math.min.apply(null,ys), yMax=Math.max.apply(null,ys);
        var xPad=(xMax-xMin)*0.18||1, yPad=(yMax-yMin)*0.18||1;
        xMin-=xPad; xMax+=xPad;
        yMax+=yPad; yMin = yMin>=0 ? 0 : yMin-yPad;
        var sMin=Math.min.apply(null,sizes), sMax=Math.max.apply(null,sizes);
        var w=460, h=360, padL=54, padR=24, padT=20, padB=54;
        var plotW=w-padL-padR, plotH=h-padT-padB;
        function xPix(v){ return padL+(v-xMin)/(xMax-xMin)*plotW; }
        function yPix(v){ return padT+(1-(v-yMin)/(yMax-yMin))*plotH; }
        function rPix(s){ var t = sMax===sMin ? 0.5 : (Math.sqrt(s)-Math.sqrt(sMin))/(Math.sqrt(sMax)-Math.sqrt(sMin)); return 12+t*26; }
        var svg = '<svg viewBox="0 0 '+w+' '+h+'" style="width:100%;max-width:480px;height:360px;display:block;">';
        svg += '<rect x="'+padL+'" y="'+padT+'" width="'+plotW+'" height="'+plotH+'" fill="none" stroke="'+SCI_AXIS+'" stroke-width="1"/>';
        niceTicksRange(yMin,yMax,6).forEach(function(t){
          var y = yPix(t);
          svg += '<line x1="'+padL+'" y1="'+y.toFixed(1)+'" x2="'+(w-padR)+'" y2="'+y.toFixed(1)+'" stroke="'+SCI_GRID+'" stroke-width="1"/>';
          svg += '<text x="'+(padL-8)+'" y="'+(y+3.5).toFixed(1)+'" text-anchor="end" font-size="10" fill="'+SCI_TEXT+'" font-family="'+SCI_FONT+'">'+t+'</text>';
        });
        niceTicksRange(xMin,xMax,6).forEach(function(t){
          var x = xPix(t);
          svg += '<text x="'+x.toFixed(1)+'" y="'+(padT+plotH+16)+'" text-anchor="middle" font-size="10" fill="'+SCI_TEXT+'" font-family="'+SCI_FONT+'">'+t+'</text>';
        });
        pts.forEach(function(p){
          var cx=xPix(p.x), cy=yPix(p.y), r=rPix(p.size);
          svg += '<circle cx="'+cx.toFixed(1)+'" cy="'+cy.toFixed(1)+'" r="'+r.toFixed(1)+'" fill="'+SCI_SINGLE+'" fill-opacity="0.55" stroke="'+SCI_AXIS+'" stroke-width="0.75"/>';
          var labelY = cy-r-8; if(labelY < padT+10) labelY = padT+10;
          svg += '<text x="'+cx.toFixed(1)+'" y="'+labelY.toFixed(1)+'" text-anchor="middle" font-size="10.5" font-weight="700" fill="'+SCI_TEXT+'" font-family="'+SCI_FONT+'">'+p.label+'</text>';
        });
        svg += '<text x="'+(padL+plotW/2)+'" y="'+(h-24)+'" text-anchor="middle" font-size="11" fill="'+SCI_TEXT+'" font-family="'+SCI_FONT+'">'+xName+'</text>';
        svg += '<text x="14" y="'+(padT+plotH/2)+'" text-anchor="middle" font-size="11" fill="'+SCI_TEXT+'" font-family="'+SCI_FONT+'" transform="rotate(-90 14 '+(padT+plotH/2)+')">'+yName+'</text>';
        svg += '</svg>';
        var caption = '<div style="text-align:center;font-size:11px;font-style:italic;color:'+SCI_TEXT+';font-family:'+SCI_FONT+';margin-top:2px;">Bubble size = '+sizeName+'</div>';
        var legend = '<div style="display:flex;flex-wrap:wrap;gap:14px;justify-content:center;margin-top:6px;font-family:'+SCI_FONT+';">';
        pts.forEach(function(p){ legend += '<div style="font-size:11px;color:'+SCI_TEXT+';">'+p.label+': '+p.sizeDisplay+'</div>'; });
        legend += '</div>';
        return '<div style="margin:14px 0;padding:16px;border:1px solid '+SCI_AXIS+';border-radius:0;background:var(--qz-bg);">'+svg+caption+legend+'</div>';
      }

      function questionTextHTML(q){
        var html = (q.text||'').replace(/\n/g,'<br>');
        if(q.table){
          var renderers = {bar:buildBarChartHTML, line:buildLineChartHTML, pie:buildPieChartHTML, 'horizontal-bar':buildHorizontalBarHTML, scatter:buildScatterChartHTML, bubble:buildBubbleChartHTML, 'stacked-bar':buildStackedBarHTML, combo:buildComboChartHTML, 'bubble-xy':buildBubbleXYChartHTML};
          var renderFn = renderers[q.chartType] || buildTableHTML;
          html = html.replace('[[TABLE]]', renderFn(q.table));
        }
        return html;
      }

      function appendQuestion(q, i){
        const qCard = el('div', {style:'background:var(--qz-surface);border:1px solid var(--qz-border);border-radius:3px;padding:18px 20px;margin-bottom:8px;'});
        const qNum = el('div', {style:'font-size:11px;color:var(--qz-muted);margin-bottom:8px;'}, [txt('Question '+(i+1)+' of '+questions.length)]);
        const qText = el('div', {style:'font-size:14px;font-weight:400;color:var(--qz-ink);line-height:1.6;'});
        qText.innerHTML = questionTextHTML(q);
        qCard.appendChild(qNum); qCard.appendChild(qText);
        threadInner.appendChild(qCard);
        setTimeout(function(){ thread.scrollTop = thread.scrollHeight; answerInput.focus(); }, 50);
      }

      function appendAnswer(given, isCorrect, skipped){
        const row = el('div', {style:'display:flex;justify-content:flex-end;margin-bottom:4px;'});
        const youLabel = el('div', {style:'text-align:right;'});
        youLabel.innerHTML = '<div style="font-size:10px;color:var(--qz-muted);margin-bottom:4px;text-align:right;">You</div>';
        const bubble = el('div', {style:'display:inline-block;background:'+(skipped?'var(--qz-surface-alt)':'var(--qz-surface)')+';border:1px solid '+(skipped?'var(--qz-input-border)':'var(--qz-border)')+';border-radius:3px;padding:10px 16px;font-size:14px;color:'+(skipped?'var(--qz-muted)':'var(--qz-ink-soft)')+';font-style:'+(skipped?'italic':'normal')+';max-width:200px;'}, [txt(given||'Skipped')]);
        youLabel.appendChild(bubble);
        row.appendChild(youLabel);
        const ack = el('div', {style:'font-size:12px;color:var(--qz-muted);font-style:italic;margin-bottom:16px;'}, [txt(skipped?'Skipped':'Thank you')]);
        threadInner.appendChild(row);
        threadInner.appendChild(ack);
        setTimeout(function(){ thread.scrollTop = thread.scrollHeight; }, 50);
      }

      function renderQuestion(){
        const q = questions[idx];
        qLabel.textContent = 'Question '+(idx+1)+' of '+questions.length;
        answerInput.value = '';
        answerInput.disabled = false;
        submitBtn.disabled = false;
        appendQuestion(q, idx);
      }

      function checkAnswer(){
        if(answerInput.disabled) return;
        const val = normalize(answerInput.value);
        const q = questions[idx];
        const correctSet = [q.answer].concat(q.alts||[]).map(normalize);
        const isCorrect = val && correctSet.includes(val);
        const skipped = !val;
        if(isCorrect) score++;
        answers[idx] = { given: answerInput.value||'Skipped', correct:q.answer, isCorrect:isCorrect, skipped:skipped, explain:q.explain, text:q.text };
        answerInput.disabled = true; submitBtn.disabled = true;
        appendAnswer(answerInput.value||'Skipped', isCorrect, skipped);
        idx++;
        if(idx < questions.length){ setTimeout(function(){ renderQuestion(); }, 300); }
        else { stopTimer(); setTimeout(function(){ renderResults(); }, 400); }
      }

      submitBtn.onclick = checkAnswer;
      answerInput.addEventListener('keydown', function(e){ if(e.key==='Enter'){ e.preventDefault(); checkAnswer(); }});

      function renderResults(){
        answerInput.style.display='none'; submitBtn.style.display='none';
        timerEl.style.display='none'; endBtn.style.display='none';
        qLabel.textContent='';
        threadInner.innerHTML='';
        const pct = questions.length>0?Math.round((score/questions.length)*100):0;
        if(!bestScore || score > bestScore.score){ localStorage.setItem(scoreKey, JSON.stringify({score:score, total:questions.length})); }
        const scoreCard = el('div', {style:'border:1px solid var(--qz-border);border-radius:3px;padding:28px;margin-bottom:20px;text-align:center;'});
        const testTitle2 = el('div', {style:'font-size:10px;letter-spacing:2px;text-transform:uppercase;color:var(--qz-muted);margin-bottom:16px;'}, [txt(title.toUpperCase())]);
        const scoreRow = el('div', {style:'display:flex;align-items:center;justify-content:center;gap:32px;margin-bottom:16px;'});
        const s1=el('div',{}); s1.innerHTML='<div style="font-size:48px;font-weight:700;color:#A6572E;line-height:1;">'+score+'</div><div style="font-size:12px;color:var(--qz-muted);margin-top:4px;">out of '+questions.length+'</div>';
        const s2=el('div',{}); s2.innerHTML='<div style="font-size:48px;font-weight:700;color:#A6572E;line-height:1;">'+pct+'%</div><div style="font-size:12px;color:var(--qz-muted);margin-top:4px;">correct</div>';
        scoreRow.appendChild(s1); scoreRow.appendChild(el('div',{style:'width:1px;height:52px;background:var(--qz-border);'})); scoreRow.appendChild(s2);
        const msg=score===questions.length?'Perfect score.':pct>=80?'Strong result. Review any mistakes carefully.':pct>=60?'Good effort. Work through the explanations.':'Work through every explanation carefully before trying again.';
        const msgEl=el('div',{style:'background:var(--qz-surface-warm);border:1px solid var(--qz-border-warm);border-radius:3px;padding:8px 14px;font-size:13px;color:var(--qz-text-warm);'},[txt(msg)]);
        scoreCard.appendChild(testTitle2); scoreCard.appendChild(scoreRow); scoreCard.appendChild(msgEl);
        threadInner.appendChild(scoreCard);
        const bk=el('div',{style:'border:1px solid var(--qz-border);border-radius:3px;padding:20px;margin-bottom:20px;'});
        bk.appendChild(el('div',{style:'font-size:10px;letter-spacing:2px;text-transform:uppercase;color:var(--qz-muted);margin-bottom:12px;'},[txt('Question breakdown')]));
        answers.forEach(function(a,i){
          if(!a) a={given:'Skipped',isCorrect:false,skipped:true,correct:(questions[i]||{}).answer||''};
          const row=el('div',{style:'display:flex;align-items:center;justify-content:space-between;padding:8px 0;border-bottom:1px solid var(--qz-border-soft);'});
          row.appendChild(el('div',{style:'font-size:13px;color:var(--qz-ink-soft);'},[txt('Question '+(i+1))]));
          row.appendChild(el('div',{style:'font-size:12px;font-weight:600;color:'+(a.isCorrect?'var(--qz-good-text)':a.skipped?'var(--qz-muted)':'var(--qz-bad-text)')+''},[txt(a.isCorrect?'Correct':a.skipped?'Skipped':'Incorrect')]));
          bk.appendChild(row);
        });
        threadInner.appendChild(bk);
        const reviewBtn=el('button',{style:'width:100%;padding:14px;background:var(--qz-bg);border:1.5px solid #A6572E;border-radius:3px;font-size:14px;font-weight:700;color:#A6572E;cursor:pointer;font-family:Inter,sans-serif;margin-bottom:10px;'},[txt('Review all questions →')]);
        reviewBtn.onclick=function(){ renderReview(); };
        threadInner.appendChild(reviewBtn);
        const btnRow=el('div',{style:'display:grid;grid-template-columns:1fr 1fr;gap:10px;'});
        const retryBtn=el('button',{style:'padding:12px;background:var(--qz-bg);border:1px solid var(--qz-input-border);border-radius:3px;font-size:13px;font-weight:600;color:var(--qz-ink-soft);cursor:pointer;font-family:Inter,sans-serif;'},[txt('Try again')]);
        retryBtn.onclick=function(){ idx=0; score=0; answers.fill(null); secsLeft=TOTAL_SECS; answerInput.style.display=''; submitBtn.style.display=''; timerEl.style.display='flex'; endBtn.style.display=''; mainBtn.style.display=''; threadInner.innerHTML=''; renderQuestion(); startTimer(); };
        const backBtn=el('button',{style:'padding:12px;background:var(--qz-bg);border:1px solid var(--qz-input-border);border-radius:3px;font-size:13px;font-weight:600;color:var(--qz-ink-soft);cursor:pointer;font-family:Inter,sans-serif;'},[txt('Back')]);
        backBtn.onclick=function(){ cleanupQuiz(); goBack(); };
        btnRow.appendChild(retryBtn); btnRow.appendChild(backBtn);
        threadInner.appendChild(btnRow);
        thread.scrollTop=0;
        shell.querySelectorAll('.tip-link').forEach(function(el2){ el2.onclick=function(){ showTipModal(el2.dataset.key); }; });
      }

      function renderReview(){
        threadInner.innerHTML='';
        let reviewIdx=0;
        function showReviewQ(){
          threadInner.innerHTML='';
          const a=answers[reviewIdx]||{given:'Skipped',isCorrect:false,skipped:true,correct:(questions[reviewIdx]||{}).answer||'',explain:(questions[reviewIdx]||{}).explain||''};
          const q=questions[reviewIdx];
          const nav=el('div',{style:'display:flex;align-items:center;justify-content:space-between;margin-bottom:20px;'});
          const prevBtn=el('button',{style:'font-size:13px;color:var(--qz-muted);background:none;border:none;cursor:pointer;padding:4px 0;'},[txt('← Prev')]);
          prevBtn.disabled=reviewIdx===0; prevBtn.onclick=function(){ reviewIdx--; showReviewQ(); };
          const qCount=el('div',{style:'font-size:13px;font-weight:600;color:#A6572E;'},[txt('Question '+(reviewIdx+1)+' of '+questions.length)]);
          const allBtn=el('span',{style:'font-size:12px;color:var(--qz-muted);cursor:pointer;'},[txt(sourceLabel==='tests' ? 'All practice tests' : 'All drills')]);
          allBtn.onclick=function(){ shell.remove(); openResourceSection(sourceLabel==='tests' ? 'bcgquanttest' : 'drills'); };
          const nextRevBtn=el('button',{style:'font-size:13px;color:var(--qz-ink);background:var(--qz-bg);border:1px solid var(--qz-input-border);border-radius:3px;padding:5px 12px;cursor:pointer;font-family:Inter,sans-serif;'},[txt('Next →')]);
          nextRevBtn.disabled=reviewIdx>=questions.length-1; nextRevBtn.onclick=function(){ reviewIdx++; showReviewQ(); };
          nav.appendChild(prevBtn); nav.appendChild(qCount); nav.appendChild(allBtn); nav.appendChild(nextRevBtn);
          threadInner.appendChild(nav);
          const card=el('div',{style:'border:1px solid var(--qz-border);border-radius:3px;padding:22px;background:var(--qz-bg);'});
          const status=el('div',{style:'font-size:11px;letter-spacing:1.5px;text-transform:uppercase;font-weight:700;color:'+(a.isCorrect?'var(--qz-good-text)':a.skipped?'var(--qz-muted)':'var(--qz-bad-text)')+';margin-bottom:12px;'},[txt(a.isCorrect?'✓ Correct':a.skipped?'- Skipped':'✗ Incorrect')]);
          const qTextEl=el('div',{style:'font-size:14px;font-weight:400;color:var(--qz-ink);margin-bottom:18px;line-height:1.6;'});
          qTextEl.innerHTML=questionTextHTML(q);
          card.appendChild(status); card.appendChild(qTextEl);
          const ansRow=el('div',{style:'display:grid;grid-template-columns:1fr 1fr;gap:10px;margin-bottom:16px;'});
          const yourBox=el('div',{style:(a.isCorrect?'background:var(--qz-good-bg);border:1px solid var(--qz-good-border);':'background:var(--qz-surface);border:1px solid var(--qz-border);')+'border-radius:3px;padding:10px 12px;'});
          yourBox.innerHTML='<div style="font-size:9px;letter-spacing:2px;text-transform:uppercase;color:'+(a.isCorrect?'var(--qz-good-text)':'var(--qz-muted)')+';margin-bottom:5px;">Your answer</div><div style="font-size:15px;color:'+(a.isCorrect?'var(--qz-good-text)':'var(--qz-ink-soft)')+';font-weight:'+(a.isCorrect?'700':'400')+';font-style:'+(a.isCorrect?'normal':'italic')+';">'+(a.skipped?'Skipped':formatAnswer(a.given))+'</div>';
          const corrBox=el('div',{style:'background:var(--qz-good-bg);border:1px solid var(--qz-good-border);border-radius:3px;padding:10px 12px;'});
          corrBox.innerHTML='<div style="font-size:9px;letter-spacing:2px;text-transform:uppercase;color:var(--qz-good-text);margin-bottom:5px;">Correct answer</div><div style="font-size:15px;color:var(--qz-good-text);font-weight:700;">'+formatAnswer(a.correct||q.answer||'')+'</div>';
          ansRow.appendChild(yourBox); ansRow.appendChild(corrBox);
          card.appendChild(ansRow);
          if(a.explain||q.explain){
            const solHead=el('div',{style:'font-size:10px;letter-spacing:2px;text-transform:uppercase;color:#A6572E;font-weight:700;margin-bottom:10px;'},[txt('Worked solution')]);
            const solBody=el('div',{style:'font-size:13.5px;color:var(--qz-ink-soft);line-height:1.75;'});
            solBody.innerHTML=formatSolution(a.explain||q.explain||'');
            card.appendChild(solHead); card.appendChild(solBody);
          }
          threadInner.appendChild(card);
          const backRes=el('button',{style:'width:100%;padding:12px;background:var(--qz-bg);border:1.5px solid #A6572E;border-radius:3px;font-size:13px;font-weight:600;color:#A6572E;cursor:pointer;font-family:Inter,sans-serif;margin-top:14px;'},[txt('Back to results')]);
          backRes.onclick=function(){ renderResults(); };
          threadInner.appendChild(backRes);
          thread.scrollTop=0;
          setTimeout(function(){ threadInner.querySelectorAll('.tip-link').forEach(function(el2){ el2.onclick=function(){ showTipModal(el2.dataset.key); }; }); }, 100);
        }
        showReviewQ();
      }

      renderQuestion();
      startTimer();
    }

    showPreTest(function(){
      showCameraModal(function(){
        startQuiz();
      });
    });

    const placeholder = el('div', {id:'quiz-placeholder'}); return placeholder;
  }


  /* ---------- McKINSEY / BCG / BAIN ONLINE TESTS (chooser) ---------- */
  function renderPracticeTests(){
    const wrap = pageWrap('Quant Skillset', 'McKinsey, BCG, Bain Online Tests',
      'Each firm screens quant ability with a different online assessment before the case interview stage. Practice the format that matches the firm you are applying to.');

    if(!document.getElementById('mbb-card-css')){
      const mbbCSS = `
        .mbb-card-grid{ display:grid; grid-template-columns:repeat(3,1fr); gap:20px; margin:8px 0 8px; }
        @media (max-width:760px){ .mbb-card-grid{ grid-template-columns:1fr; } }
        .mbb-card{ background:var(--bg-card); border:0.5px solid var(--line); border-radius:8px; padding:26px 22px; position:relative; transition:background .25s ease, transform .2s ease; }
        html:not([data-theme="dark"]) .mbb-card{ background:#faf9f6; }
        .mbb-card-badge{ display:inline-block; font-size:9.5px; letter-spacing:1.6px; text-transform:uppercase; font-weight:700; padding:4px 9px; border-radius:4px; margin-bottom:14px; }
        .mbb-card-badge--active{ color:var(--gold-bright); background:var(--card-featured-bg); }
        .mbb-card-badge--locked{ color:var(--faint); background:var(--bg-raised); border:1px solid var(--line); }
        .mbb-card-title{ font-family:var(--serif-heading); font-weight:700; font-size:18px; color:var(--ink); margin-bottom:10px; padding-right:20px; }
        .mbb-card-desc{ font-size:13.5px; color:var(--muted); line-height:1.65; }
        .mbb-card-arrow{ position:absolute; top:26px; right:20px; color:var(--gold-dim); font-size:15px; opacity:0; transform:translateX(-4px); transition:opacity .2s ease, transform .2s ease, color .2s ease; }
        .mbb-card.is-active{ cursor:pointer; }
        .mbb-card.is-active:hover{ background:var(--card-hover); transform:translateY(-3px); }
        html:not([data-theme="dark"]) .mbb-card.is-active:hover{ background:var(--card-hover); }
        .mbb-card.is-active:hover .mbb-card-arrow{ opacity:1; transform:translateX(0); color:var(--gold-bright); }
        .mbb-card.is-locked{ opacity:0.6; }
      `;
      const s=document.createElement('style'); s.id='mbb-card-css'; s.textContent=mbbCSS; document.head.appendChild(s);
    }

    function mbbCard(title, desc, opts){
      opts = opts || {};
      const card = el('div', {class:'mbb-card' + (opts.active ? ' is-active' : ' is-locked')});
      if(opts.active) card.setAttribute('role','button');
      if(opts.active) card.setAttribute('tabindex','0');
      card.appendChild(el('div', {class:'mbb-card-badge ' + (opts.active ? 'mbb-card-badge--active' : 'mbb-card-badge--locked')}, [txt(opts.badge)]));
      card.appendChild(el('div', {class:'mbb-card-title'}, [txt(title)]));
      card.appendChild(el('div', {class:'mbb-card-desc'}, [txt(desc)]));
      if(opts.active){
        card.appendChild(el('span', {class:'mbb-card-arrow'}, [txt('→')]));
        card.onclick = opts.onclick;
      }
      return card;
    }

    const grid = el('div', {class:'mbb-card-grid'});
    grid.appendChild(mbbCard(
      'McKinsey Game',
      'Interactive business-simulation games - data analysis, resource optimisation under constraints, and judgment calls under pressure.',
      {badge:'Writing in progress'}
    ));
    grid.appendChild(mbbCard(
      'BCG-Style Practice Tests',
      '20 full-length tests blending numeric foundations with business-style word problems, calibrated to real assessment difficulty. 400 questions in total, all with full worked solutions.',
      {badge:'20 tests \u00b7 400 questions', active:true, onclick:function(){ openResourceSection('bcgquanttest'); }}
    ));
    grid.appendChild(mbbCard(
      'Bain SOVA Assessment',
      'Verbal, numerical and logical reasoning sections plus a behavioural component, used to screen analytical ability and cultural fit ahead of the case rounds.',
      {badge:'Writing in progress'}
    ));
    wrap.appendChild(grid);

    linkifyGlossaryTerms(wrap);
    wrap.appendChild(footerNav([
      {label:'Study Hub', onclick:function(){ openResourceSection('resources'); }},
      {label:'Interview Skillset', onclick:function(){ prepPathOpenResourceStage('stage-interviews'); }},
      {label:'Talent Acquisition Calls', primary:true, onclick:function(){ openResourceSection('talent'); }}
    ]));
    return wrap;
  }

  /* ---------- BCG QUANT TEST ---------- */
  function renderBCGQuantTest(){
    const wrap = pageWrap('Quant Skillset', 'BCG-Style Practice Tests',
      'Full-length tests blending numeric foundations, business maths, and chart interpretation - calibrated to real difficulty.');
    const ptIntro = el('div', {style:'font-size:13.5px;color:var(--muted);line-height:1.75;margin:-24px 0 12px;'});
    ptIntro.innerHTML = 'Prefer to build up first? Try <a href="#" onclick="event.stopPropagation();openResourceSection(\'mentalmaths\');return false;" style="color:var(--gold);text-decoration:underline;">Mental Maths Theory &amp; Practice</a> or <a href="#" onclick="event.stopPropagation();openResourceSection(\'drills\');return false;" style="color:var(--gold);text-decoration:underline;">Numeric Foundations Drills</a>.';
    wrap.appendChild(ptIntro);
    const allTests = (window.TESTS || (typeof TESTS !== 'undefined' ? TESTS : []));
    const bm = allTests.filter(function(t){ return t.section==='bm'; });

    if(!document.getElementById('drills-css')){
      const drCSS=`.drills-list{display:flex;flex-direction:column;gap:0;border-bottom:1px solid var(--line);} .drills-item{display:flex;align-items:center;justify-content:space-between;padding:18px 2px;border-top:1px solid var(--line);cursor:pointer;transition:opacity .15s;} .drills-item:hover{opacity:0.7;padding-left:8px;} .drills-item-left{} .drills-item-title{font-family:var(--serif-heading);font-size:19px;font-weight:500;color:var(--ink);margin-bottom:3px;} .drills-item-desc{font-size:13px;color:var(--muted);line-height:1.6;} .drills-item-arrow{color:var(--gold);font-size:18px;flex-shrink:0;margin-left:16px;} .drills-levels-badge{font-size:10px;letter-spacing:1.5px;text-transform:uppercase;color:var(--gold);font-weight:700;}`;
      const ds=document.createElement('style');ds.id='drills-css';ds.textContent=drCSS;document.head.appendChild(ds);
    }
    if(!document.getElementById('pt-practice-extras-css')){
      const ptExtrasCSS = `.pt-practice-list .drills-item{ padding:12px 0; }`;
      const ptEs=document.createElement('style');ptEs.id='pt-practice-extras-css';ptEs.textContent=ptExtrasCSS;document.head.appendChild(ptEs);
    }

    function group(label, tests){
      if(!tests.length) return;
      if(label) wrap.appendChild(el('h3', {class:'app-subhead'}, [txt(label)]));
      const list = el('div', {class:'drills-list pt-practice-list'});
      tests.forEach(function(t){
        const item = el('div', {class:'drills-item', role:'button', tabindex:'0'});
        const left = el('div', {class:'drills-item-left'});
        left.appendChild(el('div', {class:'drills-item-title'}, [txt(t.name)]));
        left.appendChild(el('div', {class:'drills-item-desc'}, [txt(t.desc)]));
        left.appendChild(el('div', {class:'drills-levels-badge', style:'margin-top:5px;'}, [txt(t.questions.length + ' questions')]));
        const arrow = el('span', {class:'drills-item-arrow'}, [txt('→')]);
        item.appendChild(left); item.appendChild(arrow);
        item.onclick = function(){ showApp('quiz', function(){ return renderQuiz(t.questions, (label || 'BCG-Style Practice Tests') + ' - ' + t.name, 'tests'); }); };
        list.appendChild(item);
      });
      wrap.appendChild(list);
    }

    group(null, bm);
    linkifyGlossaryTerms(wrap);
    wrap.appendChild(footerNav([
      {label:'← Numeric Foundations Drills', onclick:function(){ openResourceSection('drills'); }},
      {label:'Home', primary:true, onclick:function(){ goMain(); }}
    ]));
    return wrap;
  }


  /* ---------- REGISTER SECTIONS & INIT ---------- */
  // Register all sections with the router
  /* ---------- CASE THEORY & PRACTICE (chooser) ---------- */
  // One card on the main page opens this; from here the visitor picks either
  // the theory section or the practice section. Both already exist on their own.
  function renderCaseHub(){
    const wrap = pageWrap('Interview Skillset', 'Case Theory and Practice',
      'Two ways in. Learn the structures a case is built around, or work through full cases with model answers. Pick whichever matches where you are right now.');

    const grid = el('div', {class:'sh-cta-grid'});

    const tileTheory = el('div', {class:'sh-cta-tile theory', role:'button', tabindex:'0'});
    tileTheory.appendChild(el('h4', {}, [txt('Case Interview Theory')]));
    tileTheory.appendChild(el('p', {}, [txt('The structures, math, and frameworks case interviews are built around.')]));
    tileTheory.appendChild(el('span', {class:'sh-cta-link'}, [txt('Explore Theory →')]));
    tileTheory.onclick = function(){ openResourceSection('casetheory'); };
    grid.appendChild(tileTheory);

    const tilePractice = el('div', {class:'sh-cta-tile practice', role:'button', tabindex:'0'});
    tilePractice.appendChild(el('h4', {}, [txt('Case Interview Practice')]));
    tilePractice.appendChild(el('p', {}, [txt('Full worked cases with model answers, at every difficulty level.')]));
    tilePractice.appendChild(el('span', {class:'sh-cta-link'}, [txt('Start Practising →')]));
    tilePractice.onclick = function(){ openResourceSection('casepractice'); };
    grid.appendChild(tilePractice);

    wrap.appendChild(grid);

    wrap.appendChild(footerNav([
      {label:'← Back', onclick:goBack},
      {label:'Main Page', primary:true, onclick:goMain}
    ]));

    return wrap;
  }

